async function notices(c){const{data:n}=await db.from("notices").select("*").order("id",{ascending:!1}),i=NOTICE.includes(me.role);c.innerHTML=`<div class="f">${prBtn("pn","Print all notices")}</div><div style="height:10px"></div>${i?'<div class="card"><input id="nt" placeholder="Notice title"><div style="height:8px"></div><button id="ns">Post notice</button></div>':""}
 <div class="card">${(n||[]).map(t=>`<div class="it"><div>${esc(t.title)}<small>${t.created_on}</small></div>${i?`<button class="ghost" data-n="${t.id}">Delete</button>`:""}</div>`).join("")||"No notices yet."}</div>`,$("#pn").onclick=()=>printHTML("Notices",sheetHead("Notice board")+ptable(["Sl.No","Date","Notice"],(n||[]).map((t,e)=>[e+1,esc(t.created_on),esc(t.title)]),null,["c","",""])+SIG),i&&($("#ns").onclick=async()=>{const t=$("#nt").value.trim();if(!t)return;const{error:e}=await db.from("notices").insert({title:t});e?toast(e.message):render()},document.querySelectorAll("[data-n]").forEach(t=>t.onclick=async()=>{await db.from("notices").delete().eq("id",t.dataset.n),render()}))}
